// Current SourceRecord interface (lines ~50-80)
export interface SourceRecord {
    id: string;
    projectId: string;
    type: 'text' | 'url' | 'pdf';
    title: string;
    content: string;
    charCount?: number;
    wordCount?: number;
    pageCount?: number;
    url?: string;
    createdAt: number;
    updatedAt: number;
    // TODO: Add metadata fields in Story 6.4:
    // summary?: string;
    // keyConcepts?: string[];
    // suggestedQuestions?: string[];
    // metadataExtracted?: boolean;
    // metadataEdited?: boolean;
}

// Current store structure (lines ~1-50)
import { create } from 'zustand';
